class Solution:
    def countPrimeSetBits(self, left: int, right: int) -> int:
        def is_prime(n):
            if n < 2:
                return False
            i = 2
            while i * i <= n:
                if n % i == 0:
                    return False
                i += 1
            return True

        ans = 0
        for x in range(left, right + 1):
            c = 0
            y = x
            while y:
                y &= y - 1
                c += 1
            if is_prime(c):
                ans += 1
        return ans

