class Solution {
public:
    int countPrimeSetBits(int left, int right) {
        int mask = 0b10100010100010101100; // bits 2,3,5,7,11,13,17,19 set
        int ans = 0;
        for (int x = left; x <= right; ++x)
            ans += (mask >> __builtin_popcount(x)) & 1;
        return ans;
    }
};

