class Solution {
    public int countPrimeSetBits(int left, int right) {
        Set<Integer> primes = Set.of(2, 3, 5, 7, 11, 13, 17, 19);
        int ans = 0;
        for (int x = left; x <= right; x++)
            if (primes.contains(Integer.bitCount(x))) ans++;
        return ans;
    }
}

